import{_ as o,C as p,o as d,c as r,j as a,a as e,E as n,a3 as c}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·收心","description":"坐忘论第三篇精读（全篇最长）：收心离境、不著一物；不著于物，不滞于空，由作意安养而至自然无为。","frontmatter":{"title":"坐忘论·收心","description":"坐忘论第三篇精读（全篇最长）：收心离境、不著一物；不著于物，不滞于空，由作意安养而至自然无为。","category":"guide","aliases":["坐忘论收心","收心三","坐忘论精读之四"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-03.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-03.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-03.md"};function h(u,s,b,v,m,x){const i=p("DaoReadingPrelude"),t=p("DaoTextReading"),l=p("DaoKeywordCards");return d(),r("div",null,[s[0]||(s[0]=a("h1",{id:"坐忘论·收心",tabindex:"-1"},[e("坐忘论·收心 "),a("a",{class:"header-anchor",href:"#坐忘论·收心","aria-label":'Permalink to "坐忘论·收心"'},"​")],-1)),n(i,{title:"心者一身之主，百神之帅",summary:"这是全书最长、理论最集中、也最重要的一篇。它讲收心离境、住无所有，同时逐一辨析偏差——执空、盲定、任心、口中无染。全篇的准绳是「息乱而不灭照，守静而不著空」，过程则是「随起随制，久久调熟，自得安闲」。",points:[{label:"先立心",text:"静则生慧，动则成昏——修行的第一处战场在这颗心上。"},{label:"再辨病",text:"执空、盲定、任心、口中无染，皆非真定。"},{label:"后归行",text:"法之妙用在能行不在能言；由有意安心渐至自然安闲。"}],hint:"此篇按内部层次分为六层；长文宜分段读，一段一段看它在解决哪一个问题。"}),s[1]||(s[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),s[2]||(s[2]=a("p",null,[a("strong",null,"一、心为身主")],-1)),n(t,{paragraphs:["夫心者一身之主，百神之帅，静则生慧，动则成昏。","欣迷幻境之中，唯言实是，甘宴有为之内，谁悟虚非，心识颠痴，良由所托之地。","且卜邻而居，犹从改操，择交而友，尚能致益，况身离生死之境，心居至道之中，能不舍彼乎，安不得此乎。","所以学道之初，要须安坐，收心离境，住无所有。","因住无所有，不著一物，自入虚无，心乃合道。","经云：至道之中，寂无所有，神用无方，心体亦然。","原其心体，以道为本，但为心神被染，蒙蔽渐深，流浪日久，遂与道隔。若净除心垢，开识神本，名曰修道。"]}),s[3]||(s[3]=a("p",null,[a("strong",null,"二、归根静定")],-1)),n(t,{paragraphs:["无复流浪，与道冥合，安在道中，名曰归根。守根不离，名曰静定。","静定日久，病消命复，复而又续，自得知常。知则无所不明，常则无所变灭，出离生死，实由于此。","是故法道安心，贵无所著。","经云：夫物芸芸，各归其根，归根曰静，静曰复命，复命曰常，知常曰明。","若执心住空，还是有所，非谓无所，凡住有所，则令心劳，既不合理，又反成病。","但心不著物，又得不动，此是真定。正基用此为定，心气调和，久益轻爽，以此为验，则邪正可知矣。"]}),s[4]||(s[4]=a("p",null,[a("strong",null,"三、四种错误收心法与真诀")],-1)),n(t,{paragraphs:["若心起皆灭，不简是非，则永断觉知，入于盲定。","若任心所起，一无收制，则与凡夫元来不别。","若唯断善恶，心无指归，肆意浮游，待自定者，徒自误尔。","若徧行诸事，言心无所染者，于言甚善，于行极非，真学之流，特宜诫此。","今则息乱而不灭照，守静而不著空，行之有常，自得真见。","如有时事或法要有疑者，且任思量，令事得济，所疑复悟，此亦生慧正根。","悟已则止，必莫有思，思则以智害恬，为子伤本。虽骋一时之俊，终亏万代之业。","若烦邪乱想，随觉则除，若闻毁誉之名，善恶等事，皆即拨去，莫将心受。","受之则心满，心满则道无所居。所有闻见，如不闻见，即是非善恶不入于心。","心不受外名曰虚心，心不逐外名曰安心，心安而虚，道自来居。","经云：人能虚心无为，非欲于道，道自归之。"]}),s[5]||(s[5]=a("p",null,[a("strong",null,"四、虚心安心")],-1)),n(t,{paragraphs:["内心既无所著，外行亦无所为，非净非秽，故毁誉无从生，非智非愚，故利害无由挠。","实则顺中为常，权则与时消息，苟免诸累，是其智也。","若非时非事，役思强为者，自云不著，终非真学。何耶？","心法如眼也，纤毫入眼，眼则不安，小事关心，心必动乱，既有动病，难入定门。"]}),s[6]||(s[6]=a("p",null,[a("strong",null,"五、除病如除荆棘")],-1)),n(t,{paragraphs:["是故修道之要，急在除病，病若不除，终难得定。","有如良田，荆棘未诛，虽下种子，嘉苗不茂。爱见思虑，是心荆棘，若不除翦，定慧不生。","或身居富贵，或学备经史，言则慈俭，行则贪残，辩足以饰非，势足以威物，得则名己，过则尤人，此病最深，虽学无益。"]}),s[7]||(s[7]=a("p",null,[a("strong",null,"六、调心之法")],-1)),n(t,{paragraphs:["所以然者，为自是故。然此心犹来依境，未惯独立，乍无所托，难以自安，纵得暂安，还复散乱。","随起随制，务令不动，久久调熟，自得安闲。","无问昼夜，行住坐卧，及应事之时，常须作意安之。","若心得定，即须安养，莫有恼触，少得定分，即堪自乐，渐渐驯狎，惟益清远。","平生所爱，已嫌蔽陋，况因定生慧，深达真假乎。","且牛马家畜也，放纵不收，犹自生梗，不受驾驭。鹰鹯野鸟也，为人羁绊，终日在手，自然调熟。况心之放逸，纵任不收，唯益粗疏，何能观妙。","经云：虽有拱璧，以先驷马，不如坐进此道。"]}),s[8]||(s[8]=a("p",null,[a("strong",null,"七、能行不在能言")],-1)),n(t,{paragraphs:["夫法之妙用也，其在能行，不在能言，行之则斯言为当，不行则斯言如妄。","又时人所学，贵难而贱易，若论法要，广说虚无，思虑所莫能达，行用所莫能阶者，则叹不可思议。","而下风尽礼，如其信言不美，指事直说，闻则心解，言则可行者，此实不可思议，而人翻以为浅近，而轻忽不信。","经云：吾言甚易知，甚易行，天下莫能知，莫能行。夫惟无知，是以不我知。","又有言火不热，灯不照暗，称为妙义。夫火以热为用，灯以照暗为功。","今则盛谈火不热，未尝一时废火，灯不照暗，必须终夜然灯。言行相违，理实无取，此即破相之言，而人反以为深玄之妙。","虽惠子宏辩，庄生以为不堪。肤受之流，谁能断简，至学之士，庶不留心。"]}),s[9]||(s[9]=a("p",null,[a("strong",null,"八、问答：动静取舍")],-1)),n(t,{paragraphs:["或曰：夫为大道者，在物而心不染，处动而神不乱，无事而不为，无时而不寂。今独避事而取安，离动而求定，劳于控制，乃有动静二心，滞于住守，是成取舍两病。都未觉其外执，而谓道之阶要，何其谬邪。","答曰：总物而称大，通物之谓道，在物而不染，处事而不乱，真为大矣，实为妙矣。","然谓吾子之鉴有所末明，何耶？徒见贝锦之辉焕，未晓始抽之素丝，才闻鸣鹤之冲天，讵识先资于𬆮食。","蔽日之干，起于毫末。神凝至圣，积习而成。","今徒学语其圣德，而不知圣之所以德，可谓见卯而求时夜，见弹而求鸮炙。何其造次哉。","故经云：玄德深矣，远矣，与物反矣。然后乃至大顺。"]}),s[10]||(s[10]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[e("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(l,{items:[{term:"心识颠痴",pinyin:["xīn","shí","diān","chī"],meaning:"心识，认识、分别、记忆与执取的活动；颠，以假为真、以苦为乐；痴，不能照见真实。谓心之颠倒愚痴。"},{term:"所托之地",pinyin:["suǒ","tuō","zhī","dì"],meaning:"心所依托、安放、寄居的对象或境界。心托于名则随毁誉而动，托于利则随得失而动——收心即是改变心的立足之地。"},{term:"住无所有",pinyin:["zhù","wú","suǒ","yǒu"],meaning:"使心安住于不占有、不依附任何对象的状态。非世界不存在，也非进入空白麻木，而是无所依而能住，无所有而不散。"},{term:"神用无方",pinyin:["shén","yòng","wú","fāng"],meaning:"幽微灵妙的作用没有固定方向、形式与边界。道体寂而无所有，道用则神妙无方。"},{term:"心垢",pinyin:["xīn","gòu"],meaning:"附着于心、使心失去清明的贪爱、成见、杂念与执著。是后天积累的遮蔽，非心体本身。"},{term:"开识神本",pinyin:["kāi","shí","shén","běn"],meaning:"开明其识，显发心神本有的根源（即「以道为本」）。修道的定义由此确立：净除心垢，使神本重新显明。"},{term:"盲定",pinyin:["máng","dìng"],meaning:"若心起皆灭、不简是非，则永断觉知，如盲者之定。看似无念，却无清楚觉照——与真定相对。"},{term:"息乱而不灭照",pinyin:["xī","luàn","ér","bù","miè","zhào"],meaning:"止息纷乱攀缘，但不熄灭清醒觉照。乱要息，照不可灭；念可不随，觉不可昏。本篇总诀之一。"},{term:"守静而不著空",pinyin:["shǒu","jìng","ér","bù","zhuó","kōng"],meaning:"安住于静，却不把「静」或「空」当作可执著的对象。守静防散乱，不著空防僵滞。"},{term:"虚心",pinyin:["xū","xīn"],meaning:"心不受外名曰虚心——不把见闻毁誉纳进来反复保存，解决「被占满」的问题。"},{term:"安心",pinyin:["ān","xīn"],meaning:"心不逐外名曰安心——不追随外境奔逸，解决「向外流浪」的问题。必须安而且虚。"},{term:"爱见思虑",pinyin:["ài","jiàn","sī","lǜ"],meaning:"爱，贪爱依恋；见，固执见解尤其是自以为是；思虑，无休止的分别盘算。三者相续，本篇喻为「心荆棘」。"},{term:"役思强为",pinyin:["yì","sī","qiǎng","wéi"],meaning:"役使思虑、勉强造作。谓非时非事而强行用思，虽自称不著，终非真学。"},{term:"随起随制",pinyin:["suí","qǐ","suí","zhì"],meaning:"念头一生起即随即收摄制止。重点不在禁止念头最初出现，而在阻止它继续扩展——比「心起皆灭」温和，比「任心所起」积极。"},{term:"驯狎",pinyin:["xùn","xiá"],meaning:"驯，调伏；狎，亲近熟习。渐渐驯狎，谓心经长期调习而渐熟，非以暴力压制。"},{term:"鹰鹯",pinyin:["yīng","zhān"],meaning:"鹰与鹯，皆猛禽。取「野鸟久被羁绊亦能调熟」为喻，说心虽放逸亦可调习——古代调心之喻。"},{term:"贝锦",pinyin:["bèi","jǐn"],meaning:"织成贝纹的锦。此处喻徒见其成而不见其始：只见圣人动静一如之果，不知其积习之因。"},{term:"𬆮食",pinyin:["kòu","shí"],meaning:"依底本保留。结合文意指幼鸟成长阶段所需的饮食滋养（相关版本或有异文）。鸣鹤冲天，先资于𬆮食。"},{term:"见卯而求时夜",pinyin:["jiàn","mǎo","ér","qiú","shí","yè"],meaning:"底本作「卯」，常见文字作「卵」（见卵而求时夜）。时夜即司晨之鸡。见卵便求报晓之鸡，喻求成太急、不知次序。"},{term:"见弹而求鸮炙",pinyin:["jiàn","dàn","ér","qiú","xiāo","zhì"],meaning:"鸮炙即烤鸮鸟肉。见弹丸便想烤肉，同喻急求其成。"}]}),s[11]||(s[11]=c("",185))])}const C=o(g,[["render",h]]);export{y as __pageData,C as default};
